# -*- coding: utf-8 -*-
"""統合版DD報告書（データA用・単一分冊）のページ別コンテンツ定義。

構成（claude_code_prompt v2 第5章）：
  事業編：1.会社概要／2.市場環境／3.競合環境／4.事業モデルとKPI／5.顧客分析
  財務編：6.収益性分析（P/L）／7.B/S分析／8.CF分析／9.計画前提の評価

制約（4-2 データA固有条件）：
- 単位は千円で統一（Excel Aと完全一致。丸め由来のズレを作らない）
- 法務・税務・簿外債務・のれん差異・多段表・他分冊参照を含まない
- 事業計画の前提条件（稼働率・単価改定・CPA・採用人数）を3章以上に分散（D2）
- 60ページ以上・表30個以上（D1）

すべての財務数値は spec12（数値正本）から f-string で注入する。
"""
import spec12 as S

_pl = S.compute_pl("base")
_bs, _cf = S.compute_bs_cf("base")
_drv = S.drivers("base")
_sched = S.debt_schedule()
_mon = S.compute_monthly()
_season = S.monthly_seasonality(_mon["revenue"])

AY = S.ACTUAL_YEARS          # FY22〜26
PY = S.PLAN_YEARS            # FY27〜33


def fk(v) -> str:
    """千円の金額表示。"""
    return f"{v:,}"


def pc(x, d=1) -> str:
    return f"{x * 100:.{d}f}%"


def _row(label, series, fmt=fk):
    return [label] + [fmt(v) for v in series]


def t_actual(label_rows, header="千円"):
    """実績5期（FY22〜26）の表を組み立てる。"""
    rows = [[header] + AY]
    rows.extend(label_rows)
    return rows


def t_plan(label_rows, header="千円"):
    rows = [[header] + PY]
    rows.extend(label_rows)
    return rows


# 主要数値のショートカット
REV = {y: _pl[y]["revenue"] for y in S.YEARS}
EBITDA = {y: _pl[y]["ebitda"] for y in S.YEARS}
OP = {y: _pl[y]["op"] for y in S.YEARS}
NI = {y: _pl[y]["ni"] for y in S.YEARS}
CAGR2226 = (REV["FY26"] / REV["FY22"]) ** 0.25 - 1

# QoE調整（千円・報告値から厳密加減算）
_QOE_DX = {"FY24": 28_000, "FY25": 35_000, "FY26": 33_000}
_QOE_MOVE = {"FY24": 0, "FY25": 0, "FY26": 12_000}
_QOE_EXEC = {"FY24": -25_000, "FY25": -38_000, "FY26": -45_000}
_QOE_OTHER = {"FY24": 3_000, "FY25": 1_000, "FY26": 0}
QOE_NORM = {y: EBITDA[y] + _QOE_DX[y] + _QOE_MOVE[y] + _QOE_EXEC[y] + _QOE_OTHER[y]
            for y in ("FY24", "FY25", "FY26")}
assert QOE_NORM["FY26"] == 1_620_000

