# ================================================================ 追加分析節（見た目リアリティ増補）

def fkn(v) -> str:
    """千円表示（負値は△表記）。"""
    return f"△{abs(v):,}" if v < 0 else f"{v:,}"


# 売上ブリッジ（FY25→FY26）：数量効果・単価効果の分解（丸め整合を機械保証）
_a25, _a26 = _drv["FY25"]["active"], _drv["FY26"]["active"]
_b25, _b26 = _drv["FY25"]["bill"], _drv["FY26"]["bill"]
_VOL_EFF = int(S.excel_round((_a26 - _a25) * 166 * _b25 * 12 / 1000))
_PRICE_EFF = int(S.excel_round(_a26 * 166 * (_b26 - _b25) * 12 / 1000))
_RESID = (_pl["FY26"]["staffing_rev"] - _pl["FY25"]["staffing_rev"] - _VOL_EFF - _PRICE_EFF)
_OREV_EFF = _pl["FY26"]["other_revenue"] - _pl["FY25"]["other_revenue"]
assert _pl["FY25"]["revenue"] + _VOL_EFF + _PRICE_EFF + _RESID + _OREV_EFF == _pl["FY26"]["revenue"]

