def _cf_row_vals(years):
    rows = []
    wc = {y: _cf[y]["op_cf"] - _pl[y]["ni"] - _pl[y]["depreciation"] for y in years}
    repay = {y: (-50_000 if y in AY else -_sched[y]["repayment"]) for y in years}
    fin_other = {y: _cf[y]["fin_cf"] - repay[y] for y in years}
    rows.append(_row("税引後当期純利益", [_pl[y]["ni"] for y in years], fkn))
    rows.append(_row("減価償却費", [_pl[y]["depreciation"] for y in years], fkn))
    rows.append(_row("運転資本増減・その他", [wc[y] for y in years], fkn))
    rows.append(_row("営業キャッシュフロー", [_cf[y]["op_cf"] for y in years], fkn))
    rows.append(_row("設備投資等（投資CF）", [_cf[y]["inv_cf"] for y in years], fkn))
    rows.append(_row("フリー・キャッシュフロー", [_cf[y]["fcf"] for y in years], fkn))
    rows.append(_row("借入金返済", [repay[y] for y in years], fkn))
    rows.append(_row("配当・その他財務", [fin_other[y] for y in years], fkn))
    rows.append(_row("財務キャッシュフロー", [_cf[y]["fin_cf"] for y in years], fkn))
    rows.append(_row("現金増減", [_cf[y]["net_change"] for y in years], fkn))
    rows.append(_row("期末現金", [_cf[y]["closing_cash"] for y in years], fkn))
    return rows


